export type Easing = (t: number) => number;

export const linear = (t: number): number => t;

export const easeInQuad = (t: number): number => t * t;

export const easeOutQuad = (t: number): number => {
  const u = 1 - t;
  return 1 - u * u;
};

export const easeInOutCubic = (t: number): number =>
  t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;

export class Tween {
  private elapsed = 0;
  private _value: number;
  private onComplete?: () => void;

  constructor(
    private readonly start: number,
    private readonly end: number,
    private readonly durationTicks: number,
    private readonly easing: Easing = linear,
  ) {
    this._value = start;
  }

  get value(): number {
    return this._value;
  }

  get done(): boolean {
    return this.elapsed >= this.durationTicks;
  }

  tick(): void {
    if (this.done) return;
    this.elapsed++;
    const t =
      this.durationTicks === 0
        ? 1
        : Math.min(this.elapsed / this.durationTicks, 1);
    this._value = this.start + (this.end - this.start) * this.easing(t);
    if (this.done && this.onComplete) {
      this.onComplete();
    }
  }

  onCompleteCallback(fn: () => void): void {
    this.onComplete = fn;
  }
}

