import { describe, expect, it } from "vitest";
import {
  Tween,
  easeInQuad,
  easeInOutCubic,
  easeOutQuad,
  linear,
} from "./tween";

describe("easings", () => {
  const easings = [
    ["linear", linear],
    ["easeInQuad", easeInQuad],
    ["easeOutQuad", easeOutQuad],
    ["easeInOutCubic", easeInOutCubic],
  ] as const;

  for (const [name, fn] of easings) {
    it(`${name} maps 0 -> 0`, () => {
      expect(fn(0)).toBe(0);
    });
    it(`${name} maps 1 -> 1`, () => {
      expect(fn(1)).toBe(1);
    });
  }

  it("easeInOutCubic(0.5) === 0.5", () => {
    expect(easeInOutCubic(0.5)).toBe(0.5);
  });

  it("easeOutQuad(0.25) === 0.4375", () => {
    expect(easeOutQuad(0.25)).toBe(0.4375);
  });
});

describe("Tween", () => {
  it("10-tick linear tween from 0 to 100 reads exactly 50 after 5 ticks", () => {
    const t = new Tween(0, 100, 10, linear);
    for (let i = 0; i < 5; i++) t.tick();
    expect(t.value).toBe(50);
    expect(t.done).toBe(false);
  });

  it("completed tween clamps at end value and reports done", () => {
    const t = new Tween(0, 100, 10, linear);
    for (let i = 0; i < 10; i++) t.tick();
    expect(t.done).toBe(true);
    expect(t.value).toBe(100);
    // extra ticks keep it clamped
    t.tick();
    t.tick();
    expect(t.value).toBe(100);
  });

  it("chained tween fires exactly when the first completes", () => {
    let firedAt = -1;
    let ticks = 0;
    const second = new Tween(100, 200, 5, linear);
    let secondStarted = false;

    const first = new Tween(0, 100, 10, linear);
    first.onCompleteCallback(() => {
      firedAt = ticks;
      secondStarted = true;
    });

    while (!secondStarted && ticks < 50) {
      ticks++;
      first.tick();
      if (secondStarted) break;
      second.tick();
    }

    expect(firedAt).toBe(10);
    expect(secondStarted).toBe(true);
    // second starts advancing on the very next tick
    expect(second.value).toBe(100);
    second.tick();
    expect(second.value).toBe(120);
  });
});

